{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Norethisterone, a 17α-ethynyl-17β-hydroxy-4-en-3-one 19-nor steroid, has an absolute oral bioavailability of 64% in healthy volunteers, directly supporting high F for the query's shared alkynyl-steroid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Levonorgestrel, a 13-ethyl analogue of the same 17α-ethynyl-17β-hydroxy-4-en-3-one class, has a mean absolute bioavailability of 94% across three studies, indicating minimal first-pass loss for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Etonogestrel, the active metabolite of desogestrel with the same 17α-ethynyl-17β-hydroxy-4-en-3-one pharmacophore, has an absolute bioavailability of 0.82 (95% CI 0.76-0.88) after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Moxestrol, an 11β-substituted 17α-ethynyl steroid, has an absolute oral bioavailability of 35% in humans, still above the 20% threshold and showing that 11β substitution does not abolish absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "17α-Methyltestosterone, a 17α-alkylated steroid given orally, has good oral bioavailability, supporting the oral availability of 17α-substituted steroids.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 17α-propynyl-17β-hydroxy-4-en-3-one 19-nor steroid with an 11β-(4-dimethylaminophenyl) group, closely related to orally bioavailable progestins/antiprogestins. Multiple direct human absolute-bioavailability measurements for the same alkynyl-steroid core (norethisterone 64%, levonorgestrel 94%, etonogestrel 82%) and for an 11β-substituted analogue (moxestrol 35%) all exceed 20%. The only low-F records are for structurally distinct steroids and do not transfer. Therefore F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the exact query or mifepristone was retrieved; prediction relies on close analogues.",
    "Record C10 is textually associated with abiraterone acetate but its structure is a different steroid, making its low-F result unreliable for this comparison.",
    "Human absolute F for the 11β-dimethylaminophenyl-17α-propynyl combination is inferred from class behaviour rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

